{"cards": [{"node_code": "N_5ae12538323383a9", "definition": "研究部署于道路基础设施（如路口、路段、桥梁）上的固定式检测技术与设备，旨在获取交通流参数、车辆特征及道路环境状态。", "boundary": "本节点聚焦于“固定位置”与“基础设施侧”的感知。边界在于区分“路侧固定”与“车载移动”（后者随车辆移动，归入移动交通感知）。若内容涉及检测器安装规范、路侧传感器硬件原理、固定点视频/雷达/线圈检测算法，归入本节点。若涉及基于路侧数据的宏观交通流预测或信号控制策略，需视侧重数据获取还是应用逻辑而定，通常底层检测技术归此。", "includes": ["路侧视频、雷达、微波、线圈等固定检测技术", "路侧传感器硬件设计、安装及校准方法", "基于固定检测点的交通流参数（流量、速度、占有率）提取"], "excludes": ["车载传感器、手机信令等随移动载体变化的感知技术（归入移动交通感知）", "多源数据融合算法本身（归入多源异构交通数据融合）", "交通信号控制策略或交通流预测模型（归入交通数据科学或运筹优化）"], "sibling_distinctions": [{"other_code": "N_6c36e68db8ebb0ed", "rule": "本节点关注部署在道路基础设施上的固定检测点；兄弟节点关注部署在车辆、行人或移动设备上的动态感知。"}, {"other_code": "N_4a803e1f8457659a", "rule": "本节点关注单一或同类型路侧检测源的数据获取；兄弟节点关注将路侧、车载等多类异构数据进行整合与一致性处理的方法。"}], "cross_boundary_rule": "涉及路侧传感器硬件及单点检测算法归入本节点；涉及路侧数据与车载数据的联合处理归入多源异构交通数据融合；涉及基于路侧数据的控制决策归入智能网联或运筹优化。"}, {"node_code": "N_6c36e68db8ebb0ed", "definition": "研究利用车辆、行人、无人机等移动载体搭载的传感器或通信设备，获取交通状态、环境信息及自身位置的技术领域。", "boundary": "本节点聚焦于“移动载体”与“动态感知”。边界在于区分“移动感知”与“路侧固定检测”（后者位置固定，归入路侧交通检测）。若内容涉及车载摄像头/雷达/激光雷达、手机信令、浮动车数据、V2X终端感知，归入本节点。若涉及基于移动数据的轨迹重建或地图更新，需视侧重数据采集还是数据处理而定，通常采集端技术归此。", "includes": ["车载传感器（摄像头、雷达、LiDAR）及移动感知技术", "手机信令、浮动车数据、V2X终端等移动源数据采集", "移动载体在交通环境中的动态状态获取与特征提取"], "excludes": ["部署在道路基础设施上的固定检测技术（归入路侧交通检测）", "多源数据融合算法本身（归入多源异构交通数据融合）", "基于移动数据的导航路径规划或自动驾驶控制（归入交通定位导航或智能网联）"], "sibling_distinctions": [{"other_code": "N_5ae12538323383a9", "rule": "本节点关注随车辆或行人移动的动态感知源；兄弟节点关注固定在道路上的静态检测点。"}, {"other_code": "N_4a803e1f8457659a", "rule": "本节点关注移动源的数据获取；兄弟节点关注将移动源数据与路侧等其他源数据进行融合处理的方法。"}], "cross_boundary_rule": "涉及车载/移动传感器硬件及数据采集归入本节点；涉及移动数据与路侧数据的联合处理归入多源异构交通数据融合；涉及基于移动数据的定位解算归入交通定位导航。"}, {"node_code": "N_4a803e1f8457659a", "definition": "研究将来自路侧、车载、卫星、手机等不同类型、不同时空分辨率的交通感知数据进行整合、对齐与一致性处理的技术方法。", "boundary": "本节点聚焦于“数据融合”与“一致性处理”。边界在于区分“融合方法”与“单一源检测”（单一源归入路侧或移动感知）。若内容涉及多传感器数据配准、时空对齐、冲突消解、融合算法（如卡尔曼滤波、深度学习融合），归入本节点。若涉及融合后的数据应用（如预测、控制），需视侧重融合过程还是应用逻辑而定，通常融合算法归此。", "includes": ["多源交通数据的时空对齐、配准与同步技术", "异构数据（视频、雷达、信令等）的融合算法与模型", "多源数据冲突消解、质量评估及一致性校验方法"], "excludes": ["单一类型传感器（如仅路侧视频或仅车载雷达）的检测技术（归入路侧交通检测或移动交通感知）", "基于融合数据的交通流预测、优化决策或控制策略（归入交通数据科学或运筹优化）", "交通物联网网络架构或数据传输协议（归入交通物联网与嵌入式感知）"], "sibling_distinctions": [{"other_code": "N_5ae12538323383a9", "rule": "本节点关注多源数据的整合处理；兄弟节点关注单一固定源的数据获取。"}, {"other_code": "N_6c36e68db8ebb0ed", "rule": "本节点关注多源数据的整合处理；兄弟节点关注单一移动源的数据获取。"}], "cross_boundary_rule": "涉及多源数据融合算法归入本节点；涉及单一源检测归入路侧或移动感知；涉及融合数据的应用归入数据科学或运筹优化。"}]}
